def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0

    for opp in opponents_status.values():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= 140:
                rich_opp += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, 18.0 if hp > 3 else 45.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    danger = 0
    if hp <= 2:
        danger += 2
    elif hp <= 4:
        danger += 1
    if no_water_days >= 2:
        danger += 2
    elif no_water_days >= 1:
        danger += 1

    if danger >= 3:
        bid = max(0.92 * DAILY_SALARY, highest_prev + 4.0)
    elif danger == 2:
        bid = max(0.78 * DAILY_SALARY, avg_prev + 3.0)
    else:
        if supply >= 22:
            bid = 18.0 + 4.0 * scarcity
        elif supply >= 19:
            bid = max(28.0, min(0.62 * DAILY_SALARY, avg_prev + 1.5))
        else:
            target = highest_prev + 2.0
            if highest_prev >= 100:
                target = 62.0
            elif highest_prev >= 85:
                target = 58.0
            bid = max(46.0 + 8.0 * scarcity, target)

    if urgent_opp >= 2 and supply <= 18:
        bid += 6.0
    elif rich_opp == 0 and supply >= 21 and danger == 0:
        bid -= 6.0

    if budget < DAILY_SALARY:
        bid = min(bid, max(12.0, 0.72 * budget))
    else:
        remaining_days = max(1, 10 - day_context['day'])
        reserve_floor = remaining_days * 18.0
        if budget - bid < reserve_floor and danger == 0:
            bid = max(16.0, budget - reserve_floor)

    if danger == 0 and hp >= 7 and no_water_days == 0 and supply >= 23:
        bid = min(bid, 16.0)

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for k, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday's bidding pressure from immediate previous_trace
    prev_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    prev_bids.append(float(b))
                except Exception:
                    pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Estimate how tight the day is: lower supply => higher chance opponents overbid
    # Use a smooth urgency factor based on supply position within [15,25]
    if MAX_SUPPLY - MIN_SUPPLY > 0:
        supply_pos = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        supply_pos = 0.5
    supply_pos = max(0.0, min(1.0, supply_pos))
    tightness = 1.0 - supply_pos  # 1 when supply=15, 0 when supply=25

    # Budget pressure: if many opponents likely exhausted yesterday (budget_after=0), bid less
    exhausted_count = 0
    for o in alive_opps:
        prev = o.get('previous_trace', {})
        if isinstance(prev, dict):
            ba = prev.get('budget_after', None)
            if ba is not None:
                try:
                    if float(ba) <= 0.0:
                        exhausted_count += 1
                except Exception:
                    pass
    exhausted_ratio = exhausted_count / max(1, len(alive_opps))

    # Base bid: moderate fraction of salary, increased when tightness is high and when I'm in danger
    danger = 0.0
    if hp <= 2.0:
        danger = 1.0
    elif hp <= 4.0:
        danger = 0.6
    else:
        danger = 0.2

    # If I've already gone without water, increase urgency further
    if no_water_days >= 2:
        danger = max(danger, 0.9)
    elif no_water_days == 1:
        danger = max(danger, 0.6)

    # Target bid scale
    # If opponents were bidding very high yesterday, avoid matching them unless I'm in danger.
    # Otherwise, bid enough to secure water when tightness is high.
    if highest_prev_bid >= DAILY_SALARY * 0.75:
        # They were aggressive; only overbid if I must
        base = DAILY_SALARY * (0.25 + 0.35 * tightness)
        base = base * (0.55 + 0.45 * danger)
    else:
        base = DAILY_SALARY * (0.35 + 0.25 * tightness)
        base = base * (0.6 + 0.4 * danger)

    # If many opponents exhausted, reduce bid slightly (they may be unable/willing to pay)
    base = base * (1.0 - 0.25 * exhausted_ratio)

    # Clamp bid to budget and reasonable bounds
    bid = max(0.0, min(budget, base))

    # If budget is very low, still try to preserve survival by bidding near remaining budget
    if budget <= DAILY_SALARY * 0.15:
        bid = max(0.0, min(budget, DAILY_SALARY * 0.25))

    return float(bid)
